package com.cattlefarm.admin.transfer;
import cn.dev33.satoken.stp.StpUtil;import com.baomidou.mybatisplus.core.toolkit.IdWorker;import com.cattlefarm.admin.auth.service.AuthService;import com.cattlefarm.admin.common.DataConflictException;import org.springframework.dao.EmptyResultDataAccessException;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.util.StringUtils;import java.time.LocalDateTime;import java.util.*;
@Service
public class EnhancedTransferService{
 private final JdbcTemplate jdbc;private final AuthService auth;public EnhancedTransferService(JdbcTemplate jdbc,AuthService auth){this.jdbc=jdbc;this.auth=auth;}
 public List<TransferItem>list(){long farm=auth.currentFarmId();return jdbc.query("SELECT tr.*,c.ear_tag_no,fb.barn_name from_barn,fh.herd_name from_herd,tb.barn_name to_barn,th.herd_name to_herd,u.real_name FROM transfer_record tr JOIN cattle c ON c.cattle_id=tr.cattle_id AND c.farm_id=tr.farm_id LEFT JOIN barn fb ON fb.barn_id=tr.from_barn_id LEFT JOIN herd fh ON fh.herd_id=tr.from_herd_id LEFT JOIN barn tb ON tb.barn_id=tr.to_barn_id LEFT JOIN herd th ON th.herd_id=tr.to_herd_id LEFT JOIN sys_user u ON u.user_id=tr.operator_id WHERE tr.farm_id=? ORDER BY tr.transfer_date DESC",(r,n)->new TransferItem(s(r.getLong("transfer_id")),s(r.getLong("batch_id")),s(r.getLong("cattle_id")),r.getString("ear_tag_no"),r.getString("from_barn"),r.getString("from_herd"),r.getString("to_barn"),r.getString("to_herd"),r.getTimestamp("transfer_date").toLocalDateTime(),r.getString("reason"),r.getString("real_name"),r.getInt("is_void")==1),farm);}
 @Transactional public List<TransferResponse>batch(BatchTransferRequest r,String key){long farm=auth.currentFarmId(),user=StpUtil.getLoginIdAsLong();Long replay=replay(farm,user,key,"/api/v1/transfers/batch");if(replay!=null)return responses(replay);Set<String>unique=new HashSet<>();for(var i:r.items())if(!unique.add(i.cattleId()))throw new DataConflictException("批量转群中牛只不能重复");long barn=parse(r.toBarnId(),"栏舍");Long herd=StringUtils.hasText(r.toHerdId())?parse(r.toHerdId(),"牛群"):null;String barnName=jdbc.queryForObject("SELECT barn_name FROM barn WHERE farm_id=? AND barn_id=? AND status='ENABLED'",String.class,farm,barn);if(barnName==null)throw new DataConflictException("目标栏舍不可用");if(herd!=null){Integer n=jdbc.queryForObject("SELECT COUNT(*) FROM herd WHERE farm_id=? AND herd_id=? AND barn_id=? AND status='ENABLED'",Integer.class,farm,herd,barn);if(n==null||n==0)throw new DataConflictException("目标牛群不可用或不属于目标栏舍");}long batch=IdWorker.getId();idem(farm,user,key,"/api/v1/transfers/batch",batch);jdbc.update("INSERT INTO transfer_batch(batch_id,farm_id,transfer_type,transfer_date,reason,operator_id,total_count,created_by,updated_by) VALUES(?,?,'BATCH',?,?,?,?,?,?)",batch,farm,r.transferDate(),r.reason().trim(),user,r.items().size(),user,user);for(var item:r.items()){long cattle=parse(item.cattleId(),"牛只");Map<String,Object>before;try{before=jdbc.queryForMap("SELECT barn_id,herd_id,presence_status FROM cattle WHERE farm_id=? AND cattle_id=?",farm,cattle);}catch(EmptyResultDataAccessException e){throw new DataConflictException("批量中牛只不存在");}if(!"IN_FIELD".equals(before.get("presence_status")))throw new DataConflictException("批量中包含已离场牛只");if(Objects.equals(before.get("barn_id"),barn)&&Objects.equals(before.get("herd_id"),herd))throw new DataConflictException("批量中包含已在目标位置的牛只");int n=jdbc.update("UPDATE cattle SET barn_id=?,herd_id=?,updated_by=?,version=version+1 WHERE cattle_id=? AND farm_id=? AND version=? AND presence_status='IN_FIELD'",barn,herd,user,cattle,farm,item.version());if(n==0)throw new DataConflictException("批量中牛只档案已变化，请刷新重试");long transfer=IdWorker.getId();jdbc.update("INSERT INTO transfer_record(transfer_id,batch_id,farm_id,cattle_id,from_herd_id,from_barn_id,to_herd_id,to_barn_id,transfer_date,reason,operator_id,created_by,updated_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)",transfer,batch,farm,cattle,before.get("herd_id"),before.get("barn_id"),herd,barn,r.transferDate(),r.reason().trim(),user,user,user);jdbc.update("INSERT INTO cattle_event(event_id,farm_id,cattle_id,event_type,event_date,business_table,business_id,summary,operator_id,is_void) VALUES(?,?,?,?,?,'transfer_record',?,?,?,0)",IdWorker.getId(),farm,cattle,"CATTLE_TRANSFERRED",r.transferDate(),transfer,"批量转群至栏舍："+barnName,user);}audit(farm,user,"CATTLE_BATCH_TRANSFERRED","TRANSFER_BATCH",batch,r.reason());return responses(batch);}
 @Transactional public TransferItem voidTransfer(long id,VoidTransferRequest r,String key){long farm=auth.currentFarmId(),user=StpUtil.getLoginIdAsLong();Long old=replay(farm,user,key,"/api/v1/transfers/"+id+"/void");if(old!=null)return find(id);Map<String,Object>tr;try{tr=jdbc.queryForMap("SELECT * FROM transfer_record WHERE transfer_id=? AND farm_id=?",id,farm);}catch(EmptyResultDataAccessException e){throw new DataConflictException("转群记录不存在");}if(((Number)tr.get("is_void")).intValue()==1)throw new DataConflictException("转群记录已作废");long cattle=((Number)tr.get("cattle_id")).longValue();Long latest=jdbc.queryForObject("SELECT transfer_id FROM transfer_record WHERE farm_id=? AND cattle_id=? AND is_void=0 ORDER BY transfer_date DESC,created_at DESC LIMIT 1",Long.class,farm,cattle);if(latest==null||latest.longValue()!=id)throw new DataConflictException("只能作废该牛只最新的有效转群记录");Map<String,Object>current=jdbc.queryForMap("SELECT barn_id,herd_id FROM cattle WHERE farm_id=? AND cattle_id=?",farm,cattle);if(!Objects.equals(current.get("barn_id"),tr.get("to_barn_id"))||!Objects.equals(current.get("herd_id"),tr.get("to_herd_id")))throw new DataConflictException("牛只当前位置已变化，不能作废历史转群");idem(farm,user,key,"/api/v1/transfers/"+id+"/void",id);int n=jdbc.update("UPDATE cattle SET barn_id=?,herd_id=?,updated_by=?,version=version+1 WHERE cattle_id=? AND farm_id=? AND version=?",tr.get("from_barn_id"),tr.get("from_herd_id"),user,cattle,farm,r.cattleVersion());if(n==0)throw new DataConflictException("牛只位置已被其他人修改");jdbc.update("UPDATE transfer_record SET is_void=1,void_reason=?,voided_by=?,voided_at=NOW(),updated_by=? WHERE transfer_id=?",r.reason(),user,user,id);jdbc.update("UPDATE cattle_event SET is_void=1 WHERE farm_id=? AND business_table='transfer_record' AND business_id=?",farm,id);audit(farm,user,"TRANSFER_VOIDED","TRANSFER",id,r.reason());return find(id);}
 private TransferItem find(long id){return list().stream().filter(x->x.transferId().equals(s(id))).findFirst().orElseThrow(()->new DataConflictException("转群记录不存在"));}private List<TransferResponse>responses(long batch){long farm=auth.currentFarmId();return jdbc.query("SELECT tr.transfer_id FROM transfer_record tr WHERE tr.batch_id=? AND tr.farm_id=? ORDER BY tr.created_at",(r,n)->response(r.getLong(1)),batch,farm);}private TransferResponse response(long id){long farm=auth.currentFarmId();return jdbc.queryForObject("SELECT tr.*,c.version FROM transfer_record tr JOIN cattle c ON c.cattle_id=tr.cattle_id AND c.farm_id=tr.farm_id WHERE tr.transfer_id=? AND tr.farm_id=?",(r,n)->new TransferResponse(s(r.getLong("batch_id")),s(id),s(r.getLong("cattle_id")),obj(r.getObject("from_barn_id")),obj(r.getObject("from_herd_id")),obj(r.getObject("to_barn_id")),obj(r.getObject("to_herd_id")),false,null,r.getInt("version")),id,farm);}private void audit(long f,long u,String a,String t,long id,String reason){jdbc.update("INSERT INTO operation_log(operation_log_id,farm_id,user_id,module_code,action_type,business_type,business_id,reason) VALUES(?,?,?,'LOCATION',?,?,?,?)",IdWorker.getId(),f,u,a,t,id,reason);}private void idem(long f,long u,String k,String p,long id){jdbc.update("INSERT INTO idempotency_record(farm_id,user_id,idempotency_key,request_path,business_id,expires_at) VALUES(?,?,?,?,?,?)",f,u,k,p,id,LocalDateTime.now().plusDays(1));}private Long replay(long f,long u,String k,String p){try{return jdbc.queryForObject("SELECT business_id FROM idempotency_record WHERE farm_id=? AND user_id=? AND idempotency_key=? AND request_path=? AND expires_at>NOW()",Long.class,f,u,k,p);}catch(EmptyResultDataAccessException e){return null;}}private long parse(String x,String label){try{return Long.parseLong(x);}catch(Exception e){throw new DataConflictException(label+"编号格式错误");}}private static String s(long x){return Long.toString(x);}private static String obj(Object x){return x==null?null:x.toString();}
}
